// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): AP English Language and Composition,
// Unit 3, Reasoning and Organization. Our own wording and questions, written to the College Board's AP English Language and
// Composition Course and Exam Description, whose four Big Ideas are Rhetorical Situation (RHS), Claims and Evidence (CLE),
// Reasoning and Organization (REO) and Style (STL). The outline here names the Big Idea and the topic, not an objective letter,
// because the letters are not certain; the objectives are paraphrased, not quoted. Six outline topics, one skill each: the line
// of reasoning (including deductive and inductive paths); methods of development (narration, description, definition, cause and
// effect, comparison and contrast, example, process); patterns of organization (chronological, spatial, order of importance,
// problem and solution, general to specific, block and point by point); transitions and the relationships they show;
// counterargument, concession, refutation and qualification; and how sequence, position and proportion create emphasis.
// Every passage is either two short sentences of Francis Bacon's "Of Studies" (1625, public domain, capitalization modernized)
// or labelled "Fictional passage" and written for this unit; nothing is quoted from a copyrighted text, and every invented
// number is labelled fictional. Every question offers lettered choices in its prompt and takes the letter (or the choice's own
// words); the right letter moves.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Video pictures: figure coordinates use a 100 x 34 sketch, north/up. Flow arrows trace before labels appear. */
const sketch=(title,regions,notes=[])=>{const pts={},polys=[];regions.forEach(([label,xy,col=0],i)=>{const v=xy.map(([x,y],k)=>{const n=String.fromCharCode(65+k)+i;pts[n]=[x,y];return n;}).join('');polys.push({v,label,col});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const flow=(title,stages)=>{const q=sketch(title,stages.map(([label],i)=>[label,[[i*36,13],[i*36+28,13],[i*36+28,25],[i*36,25]],i]),stages.map(([,detail],i)=>[i*36+14,7,detail]));q.segs=[];for(let i=0;i<2;i++){q.pts['P'+i]=[i*36+29,19];q.pts['Q'+i]=[i*36+35,19];q.segs.push({v:`P${i}Q${i}`,arrows:1,col:i,w:2});}q.hide=Object.keys(q.pts).join('');return q;};
const grid=(title,labels)=>sketch(title,labels.map((label,i)=>{const x=(i%3)*34,y=i<3?19:4;return [label,[[x,y],[x+30,y],[x+30,y+11],[x,y+11]],i%5];}));
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const pass=(title,texts,small=true)=>({t:'passages',title,texts,...(small?{small:true}:{})});
const bars=(title,bs)=>({t:'chart',kind:'bars',title,bars:bs.map(([label,value])=>({label,value}))});
const L='ABCDEF';
/* lettered choices, the right one moved to position k: returns {text, letter} */
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
const FIC='Fictional passage';
const BAC='Francis Bacon, “Of Studies” (1625), capitalization modernized';
/* the passages: [source label, lines] */
